const $ = (selector, root = document) => root.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
  home:'M3 10 12 3l9 7v10H3Z M9 20v-7h6v7', chat:'M21 11a8 8 0 0 1-8 8H6l-4 3V11a9 9 0 0 1 19 0Z',
  folder:'M3 6h6l2 2h10v12H3Z', plus:'M12 5v14M5 12h14', arrow:'m8 4 8 8-8 8M16 12H3',
  send:'M12 20V4m-6 6 6-6 6 6', sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
  spark:'m12 2 2.8 7.2L22 12l-7.2 2.8L12 22l-2.8-7.2L2 12l7.2-2.8Z',
  settings:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
  shield:'m12 3 8 3v6c0 4-4 7-8 9-4-2-8-5-8-9V6Z m-4 9 3 3 5-6',
  model:'M8 3h8v4H8ZM4 7h16v13H4ZM8 12h1m6 0h1M9 16h6M1 11v5m22-5v5',
  code:'m8 6-6 6 6 6m8-12 6 6-6 6m-3-14-2 16', designer:'m4 17 13-13 3 3L7 20H4Zm10-10 3 3',
  studio:'m9 7 9 5-9 5ZM3 3h18v18H3Z', writer:'M5 4h14v16H5Zm4 4h6m-6 4h6m-6 4h3',
  reviewer:'M5 4h14v16H5Zm3 8 3 3 5-6', researcher:'M15 15l6 6M17 9A7 7 0 1 1 3 9a7 7 0 0 1 14 0',
  people:'M15 7a3 3 0 1 1-6 0 3 3 0 0 1 6 0ZM5 21v-3a7 7 0 0 1 14 0v3M3 6a3 3 0 0 1 1 6m-3 8v-3m20-11a3 3 0 0 0-1 6m3 8v-3',
  file:'M5 2h9l5 5v15H5Zm9 0v6h5M9 12h6m-6 4h6', edit:'m4 17 13-13 3 3L7 20H4Zm10-10 3 3',
  close:'m6 6 12 12M6 18 18 6', check:'m5 12 4 4L19 6', clock:'M12 6v6l4 2M22 12A10 10 0 1 1 2 12a10 10 0 0 1 20 0',
  plug:'M8 2v5m8-5v5M6 7h12v3a6 6 0 0 1-12 0Zm6 9v6', grid:'M3 3h7v7H3Zm11 0h7v7h-7ZM3 14h7v7H3Zm11 0h7v7h-7Z',
};
const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.model}"/></svg>`;
const tile = name => `<span class="icon-tile icon">${icon(name)}</span>`;
let state = {projects:[],settings:{main_name:'Main agent',display_name:'',model_id:'',base_url:'',max_call_cost_usd:0,max_tokens:4096},roles:[],model_configured:false};
let online = false, view = 'home', scope = 'main', projectTab = 'conversation', conversation = {messages:[],approvals:[],files:[]};
let runByProject = {};
let busyScopes = new Set(), draftByScope = {}, teamByScope = {}, toastTimer, navigationVersion = 0;
const modal = $('#modal');
const currentProject = () => state.projects.find(p => p.id === scope);
const selectedAgent = () => view==='project' ? currentProject()?.agents.find(a=>a.id===runByProject[scope]) : null;
const activeScope = () => selectedAgent() ? `${scope}.${selectedAgent().id}` : scope;
const emptyConversation = () => ({messages:[],approvals:[],files:[]});
async function loadConversation(){const target=activeScope(),version=++navigationVersion;conversation=emptyConversation();render();try{const data=await api(`conversations/${target}`);if(version===navigationVersion&&target===activeScope()){conversation=data;render();}}catch(e){toast(e.message);}}
const pending = () => conversation.approvals.filter(a => a.status === 'pending' && a.expires * 1000 > Date.now());
function toast(message) { $('#toast').textContent = message; $('#toast').hidden = false; clearTimeout(toastTimer); toastTimer = setTimeout(() => $('#toast').hidden = true, 6500); }
async function api(path, method='GET', body) {
  const response = await fetch(`api/${path}`, {method, headers:{'Content-Type':'application/json','X-Swarmojo-Client':'desktop'},body:body === undefined ? undefined : JSON.stringify(body)});
  let data; try { data = await response.json(); } catch { throw new Error('Start the local Swarmojo desktop to use this feature.'); }
  if (!response.ok) throw new Error(data.error || 'Request failed.');
  return data;
}
function navButton(label, action, glyph, active, extra='') { return `<button class="nav-button ${active?'active':''}" data-action="${action}" ${active?'aria-current="page"':''}>${icon(glyph)}<span class="nav-text">${esc(label)}</span>${extra}</button>`; }
function sidebar() {
  $('#sidebar').innerHTML = `<div class="workspace-identity"><span class="mark icon">${icon('spark')}</span><div><strong>Your workspace</strong><small>Ideas into things that work.</small></div></div>
    <nav class="nav-group" aria-label="Main navigation">${navButton('Overview','home','home',view==='home')}${navButton(state.settings.main_name,'main','chat',view==='main')}${navButton('All projects','projects','grid',view==='projects',`<span class="number">${String(state.projects.length).padStart(2,'0')}</span>`)}</nav>
    <div class="side-label"><span>PROJECTS</span><button data-action="new-project" aria-label="Create project">${icon('plus')}</button></div>
    <nav class="side-projects" aria-label="Projects">${state.projects.length ? state.projects.map(p => `<button class="nav-button ${view==='project'&&scope===p.id?'active':''}" data-project="${p.id}" ${scope===p.id&&view==='project'?'aria-current="page"':''}><span class="project-dot"></span><span class="nav-text">${esc(p.name)}</span></button>`).join('') : '<p class="side-empty">A space for every idea.<br>Create your first project.</p>'}</nav>
    <div class="sidebar-bottom">${navButton('Local utilities','utilities','shield',false)}${navButton('Settings','settings','settings',view==='settings')}<button class="connection-mini ${state.model_configured?'configured':''}" data-action="settings"><span class="signal"></span><span><strong>${state.model_configured?'Model configured':'No model connected'}</strong><small>${state.model_configured?esc(state.settings.model_id):'Connect when you’re ready'}</small></span></button></div>`;
}
function top(label) { return `<div class="page-top"><span class="breadcrumb">Workspace <span>/</span> <strong>${esc(label)}</strong></span><span class="chip ${online?'gold':''}">${online?'LOCAL WORKSPACE':'STATIC PREVIEW'}</span></div>${online?'':`<div class="preview-banner glass"><span><strong>Preview mode.</strong> Start the local desktop for projects, agents and chat.</span><button class="text-button" data-action="launch">How to launch ${icon('arrow')}</button></div>`}`; }
function composer(home=false) {
  const working = busyScopes.has(activeScope()) || conversation.busy && !home;
  const project = view === 'project' ? currentProject() : null;
  const solo=selectedAgent(),paused=solo&&(!solo.enabled||solo.work_mode!=='isolated');
  const draft = draftByScope[home?'main':activeScope()] || '';
  return `${home?'':recoveryPanel()}<form class="composer" id="composer"><textarea id="message-input" name="message" aria-label="Message ${esc(solo?.name||state.settings.main_name)}" placeholder="${home?'What would you like to make happen?':project?'What would you like to build?':`Talk to ${esc(state.settings.main_name)}…`}" maxlength="12000" required ${working||paused?'disabled':''}>${esc(draft)}</textarea><div class="composer-bottom"><span class="composer-hint icon">${icon(state.model_configured?'shield':'plug')}${paused?'Turn this agent on and choose Isolated to send.':working?'Working on your request…':state.model_configured?`${esc(state.settings.model_id)} · Changes need your approval`:'Choose your model in Settings to start chatting'}</span><div class="chat-controls"><button class="send-button" aria-label="Send message" type="submit" ${working||paused?'disabled':''}>${icon('send')}</button></div></div></form>`;
}
function projectCard(p) { return `<button class="project-card glass" data-project="${p.id}"><div class="card-top">${tile('folder')}<span class="chip">${p.agents.length} AGENT${p.agents.length===1?'':'S'}</span></div><div><h3>${esc(p.name)}</h3><p>${esc(p.brief||'Your next idea starts here.')}</p></div><div class="card-footer"><span>Open workspace</span><span class="icon">${icon('arrow')}</span></div></button>`; }
function home() {
  const now = new Date(), hour = now.getHours();
  const greeting = hour < 12 ? 'Good morning' : hour < 18 ? 'Good afternoon' : 'Good evening';
  return top('Overview')+`<div class="home-layout"><section class="home-primary"><div class="eyebrow"><i></i> A LITTLE AMBITION. A LOT OF POSSIBILITY.</div><h1 class="greeting">${greeting}${state.settings.display_name?', '+esc(state.settings.display_name):''}.</h1><p class="subtitle">Your ideas, with a little more momentum.</p>${composer(true)}<div class="quick-actions"><button class="pill" data-draft="Help me organize my priorities and plan my day.">${icon('sun')} Plan my day</button><button class="pill" data-action="new-project">${icon('plus')} Start a project</button><button class="pill" data-draft="Help me explore and shape a new idea.">${icon('spark')} Explore an idea</button></div>
    <div class="intro-card glass">${tile('people')}<div><h3>Your project. Your team.</h3><p>Start with an idea. Bring in a Coder, Designer, Writer or another specialist when you need one. Name them your way.</p><button class="text-button" data-action="new-project">Create your first step ${icon('arrow')}</button></div></div>
    <div class="section-heading"><h2>Your projects <span class="muted small">${state.projects.length?` · ${state.projects.length}`:''}</span></h2><button class="text-button" data-action="projects">See all ${icon('arrow')}</button></div>
    ${state.projects.length?`<div class="project-grid">${state.projects.slice(0,3).map(projectCard).join('')}</div>`:`<div class="empty-project glass">${tile('folder')}<h3>Something good starts here.</h3><p>No projects yet. Give your next idea a place to grow.</p><button class="text-button spaced" data-action="new-project">${icon('plus')} Create a project</button></div>`}</section>
    <aside class="right-panel" aria-label="Workspace summary"><div class="date-panel"><div class="day">${esc(now.toLocaleDateString(undefined,{weekday:'long'}))}</div><div class="date">${esc(now.toLocaleDateString(undefined,{month:'long',day:'numeric'}))}</div><div class="year">${now.getFullYear()} · A fresh perspective</div></div><div class="section-heading"><h2>At a glance</h2></div><div class="metrics"><div class="metric"><strong>${String(state.projects.length).padStart(2,'0')}</strong><span>Projects</span></div><div class="metric"><strong>${String(state.projects.reduce((n,p)=>n+p.agents.length,0)).padStart(2,'0')}</strong><span>Assigned agents</span></div></div><div class="model-card glass"><div class="icon">${icon('model')}</div><h3>${state.model_configured?'Your model, your choice.':'A mind for your workspace.'}</h3><p>${state.model_configured?`${esc(state.settings.model_id)} is configured. Every conversation uses your selected provider.`:'Connect a local or cloud model to bring your Main agent and project specialists to life.'}</p><button class="secondary" data-action="settings">${icon('plug')} ${state.model_configured?'Model settings':'Connect a model'}</button></div><div class="footnote icon">${icon('shield')}<span>Projects stay on this machine. You choose the model, the team, and which changes get applied.</span></div></aside></div>`;
}
function projectsPage() { return top('Projects')+`<div class="page-heading"><div><div class="eyebrow">A PLACE FOR YOUR NEXT IDEA</div><h1>Your projects</h1><p class="subtitle">Give each project its own brief, conversation and team.</p></div><button class="primary" data-action="new-project">${icon('plus')} New project</button></div>${state.projects.length?`<div class="project-grid">${state.projects.map(projectCard).join('')}</div>`:`<div class="empty-project glass spaced">${tile('folder')}<h3>A clean slate.</h3><p>Create a project first. Add your specialists when you’re ready.</p><button class="primary spaced" data-action="new-project">Create project</button></div>`}`; }
function messages() {
  return `<div class="messages" aria-live="polite">${conversation.messages.map(m=>`<article class="message ${esc(m.role)}"><div class="message-heading">${esc(m.name)} ${m.metadata.simulated?'<span class="chip">SIMULATED</span>':''}<time>${esc(new Date(m.created*1000).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}))}</time></div><div class="message-content">${esc(m.content)}</div>${m.metadata.proposals?.length?`<button class="text-button spaced" data-tab="approvals">Review ${m.metadata.proposals.length} proposed action${m.metadata.proposals.length===1?'':'s'} ${icon('arrow')}</button>`:''}</article>`).join('')}</div>${busyScopes.has(activeScope())||conversation.busy?'<p class="pending-label" role="status">Your agent is working. You can visit another project while it responds.</p>':''}`;
}
function mainPage() { return top(state.settings.main_name)+`<div class="chat-layout"><div class="page-heading"><div><div class="eyebrow">YOUR EVERYDAY THINKING PARTNER</div><h1>${esc(state.settings.main_name)}</h1><p class="subtitle">A conversation for everything beyond a single project.</p></div><button class="secondary" data-action="search-history">${icon('researcher')} Search history</button></div><div class="spaced">${conversation.messages.length?messages():`<div class="chat-empty">${tile('spark')}<h2>What’s on your mind?</h2><p>Talk through an idea, ask a question, or figure out your next step. This conversation stays separate from your projects.</p></div>`}</div>${composer()}<div class="quick-actions"><button class="pill" data-draft="Help me think through an idea.">${icon('spark')} Think with me</button><button class="pill" data-draft="Help me plan my priorities for today.">${icon('sun')} Plan my day</button></div></div>`; }
function approvals() { return conversation.approvals.length?conversation.approvals.map(a=>{
  const action = a.action.action, expired = a.status==='pending' && a.expires*1000 <= Date.now();
  const label = action.tool==='run_command'?'Run command':`Write ${action.args.path}`;
  return `<article class="approval glass"><div class="approval-header"><h3>${esc(label)}</h3><span class="chip">${expired?'EXPIRED':esc(a.status.toUpperCase())}</span></div><details><summary>Review exact ${action.tool==='run_command'?'command':'file contents'}</summary><pre>${esc(action.tool==='run_command'?JSON.stringify(action.args.argv):action.args.content)}</pre><p class="workspace-path">Fingerprint: ${esc(a.fingerprint)}</p><p class="small muted">${action.tool==='run_command'?'Runs in the project sandbox with no network access.':'Applies only if the file still matches the reviewed version.'}</p></details>${a.status==='pending'&&!expired?`<div class="approval-actions"><button class="primary" data-approval="${a.request_id}" data-fingerprint="${a.fingerprint}" data-decision="approve">${icon('check')} ${action.tool==='run_command'?'Approve & run':'Approve & apply'}</button><button class="secondary" data-approval="${a.request_id}" data-fingerprint="${a.fingerprint}" data-decision="reject">Reject</button></div>`:''}${a.result?`<pre class="receipt">${esc(JSON.stringify(a.result,null,2))}</pre>`:''}</article>`;
 }).join(''):`<div class="empty-project glass">${tile('shield')}<h3>Nothing waiting for approval.</h3><p>Proposed file changes and commands will appear here for your review.</p></div>`; }
function projectPage() {
  const p=currentProject();if(!p)return projectsPage();const solo=selectedAgent();
  const tabs=solo?['conversation','files','approvals']:['conversation','files','approvals','tasks','memory','web','activity'];
  if(!tabs.includes(projectTab))projectTab='conversation';
  const body=projectTab==='web'?webPanel():projectTab==='tasks'?tasksPanel():projectTab==='memory'?memoryPanel():projectTab==='activity'?activityPanel():projectTab==='approvals'?approvals():projectTab==='files'?`${conversation.files.length?`<div class="glass">${conversation.files.map(f=>`<div class="file-row icon">${icon('file')}${esc(f)}</div>`).join('')}</div>`:'<div class="empty-project glass"><h3>No files here yet.</h3><p>Review and apply a proposed file to add it to this workspace.</p></div>'}<p class="workspace-path">Workspace: ${esc(conversation.workspace||'Loading…')}</p>`:`${conversation.messages.length?messages():`<div class="chat-empty">${tile(solo?'model':'folder')}<h2>${solo?`Work with ${esc(solo.name)}.`:`Let’s make ${esc(p.name)} happen.`}</h2><p>${solo?'Only this specialist responds in this conversation.':'Talk with your Main agent or choose Team to work with your active team specialists.'}</p></div>`}${composer()}`;
  return top(p.name)+`<div class="page-heading"><div><div class="eyebrow">PROJECT WORKSPACE</div><h1>${esc(p.name)}</h1></div><div class="header-buttons"><button class="secondary" data-action="edit-project">${icon('edit')} Project details</button><button class="secondary" data-action="project-options">${icon('settings')} Controls</button><button class="primary" data-action="add-agent">${icon('plus')} Add agent</button></div></div>${p.brief?`<p class="project-brief">${esc(p.brief)}</p>`:''}
  <div class="project-layout"><section class="project-work"><div class="work-selector glass"><label for="project-run-mode">Work with</label><select id="project-run-mode"><option value="main" ${!runByProject[scope]||runByProject[scope]==='main'?'selected':''}>${esc(state.settings.main_name)}</option><option value="team" ${runByProject[scope]==='team'?'selected':''}>Team · ${p.agents.filter(a=>a.enabled&&a.work_mode!=='isolated').length} active</option>${p.agents.map(a=>`<option value="${a.id}" ${solo?.id===a.id?'selected':''}>${esc(a.name)} · isolated${!a.enabled?' (off)':a.work_mode!=='isolated'?' (inactive)':''}</option>`).join('')}</select><p>${solo?'Separate chat, memory, files and approvals. Project brief, budget and controls still apply.':runByProject[scope]==='team'?'Only agents that are On and in Team mode take part. Main agent combines their replies.':'Main agent responds using shared project context.'}</p>${solo?'<button class="text-button" data-action="search-history">Search isolated history</button>':''}</div><nav class="tabs" aria-label="Project sections">${tabs.map(t=>`<button data-tab="${t}" class="${projectTab===t?'selected':''}">${t[0].toUpperCase()+t.slice(1)}${t==='files'?` <span class="tab-count">${conversation.files.length}</span>`:t==='approvals'?` <span class="tab-count">${pending().length}</span>`:''}</button>`).join('')}</nav>${body}</section>
  <aside class="project-team glass"><div class="section-heading"><h2>Project agents</h2><span class="chip">${p.agents.length} ADDED</span></div><div class="agent-row"><span class="agent-avatar icon">${icon('spark')}</span><span><strong>${esc(state.settings.main_name)}</strong><small>Project coordinator</small></span></div>${p.agents.map(agentCard).join('')||'<p class="team-empty">Add the expertise this project needs.</p>'}<button class="secondary full spaced" data-action="add-agent">${icon('plus')} Add specialist</button><p class="team-note">On/off and mode changes apply to new requests. A response already underway can finish. Switching modes never merges isolated work.</p>${budgetPanel()}</aside></div>`;
}
function agentCard(a){return `<section class="agent-participation ${a.enabled?'':'agent-off'}"><button class="agent-row" data-edit-agent="${a.id}" aria-label="Edit ${esc(a.name)}"><span class="agent-avatar icon">${icon(a.role==='coder'?'code':a.role)}</span><span><strong>${esc(a.name)}</strong><small>${esc(state.roles.find(r=>r.id===a.role)?.name||a.role)}</small></span><span class="icon">${icon('edit')}</span></button><div class="agent-controls"><label class="agent-switch"><input type="checkbox" role="switch" data-agent-enabled="${a.id}" aria-label="Enable ${esc(a.name)}" ${a.enabled?'checked':''}><span>${a.enabled?'On':'Off'}</span></label><select data-agent-mode="${a.id}" aria-label="Work mode for ${esc(a.name)}"><option value="team" ${a.work_mode!=='isolated'?'selected':''}>Team</option><option value="isolated" ${a.work_mode==='isolated'?'selected':''}>Isolated</option></select></div><button class="text-button" data-open-isolated="${a.id}">${a.work_mode==='isolated'?'Open isolated workspace':'View isolated history'}</button></section>`;}
function settingsPage() { return top('Settings')+`<button class="text-button" data-action="portable">Import a project template ${icon('folder')}</button><div class="page-heading"><div><div class="eyebrow">MAKE IT YOURS</div><h1>Workspace settings</h1><p class="subtitle">Your name, your Main agent, your model.</p></div>${tile('settings')}</div><section class="settings-summary glass"><h2>${state.model_configured?esc(state.settings.model_id):'Connect your model'}</h2><p>Use an OpenAI-compatible endpoint from a local model runner or a cloud provider. Project agents keep their specialist instructions and use your selected model.</p>${state.model_configured?`<p class="workspace-path">${esc(state.settings.base_url)}</p>`:''}<button class="primary" data-action="configure">${icon('settings')} Configure workspace</button></section><div class="footnote icon">${icon('shield')}<span>Local models keep prompts on your machine. Cloud providers receive the conversation and selected project files. API keys are held only for this desktop session.</span></div>`; }
function render() { sidebar(); $('#content').innerHTML=({home,projects:projectsPage,main:mainPage,project:projectPage,settings:settingsPage}[view]||home)(); $('#footer-status').textContent=online?(state.model_configured?'MODEL CONFIGURED · APPROVALS REQUIRED':'LOCAL WORKSPACE READY · MODEL NOT CONFIGURED'):'PREVIEW · START THE LOCAL DESKTOP'; }
async function navigate(next, id) {
  const version=++navigationVersion;
  view=next; scope=next==='project'?id:'main'; projectTab='conversation'; conversation={messages:[],approvals:[],files:[]};
  $('#sidebar').classList.remove('open'); render();
  if(online && ['main','project'].includes(next)) {
    try { const data=await api(`conversations/${activeScope()}`); if(version!==navigationVersion)return; conversation=data;render(); } catch(e){toast(e.message);}
  }
  $('#content').scrollTop=0; saveSession();
}
function modalShell(title, description, content) { $('#modal-content').innerHTML=`<div class="modal-inner"><div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><p class="modal-description">${esc(description)}</p>${content}</div>`; if(!modal.open)modal.showModal(); }
function launchDialog() { modalShell('Open your local workspace','The GitHub page is a preview. Projects, model connections and approvals run in your local Swarmojo desktop.',`<pre class="code-block">pip install .
python swarmmojo.py desktop</pre><p class="workspace-path">Run these commands from your Swarmojo checkout, then open the local address printed in your terminal.</p><div class="modal-actions"><button class="secondary" data-action="close">Close</button><a class="primary" href="http://127.0.0.1:8765/">Open local workspace</a></div>`); }
function requireLocal() { if(online)return true;launchDialog();return false; }
function field(label, name, value='', options={}) {return `<div class="field"><label for="field-${options.id||name}">${label}</label>${options.textarea?`<textarea id="field-${options.id||name}" name="${name}" maxlength="${options.max||6000}" ${options.required?'required':''}>${esc(value)}</textarea>`:`<input id="field-${options.id||name}" name="${name}" value="${esc(value)}" type="${options.type||'text'}" ${options.required?'required':''} ${options.extra||''} maxlength="${options.max||1000}" autocomplete="${options.type==='password'?'off':'on'}">`}${options.help?`<small>${esc(options.help)}</small>`:''}</div>`;}
function projectDialog(edit=false) {
  if(!requireLocal())return; const p=edit?currentProject():null;
  modalShell(edit?'Project details':'Start a project','One idea, one workspace. Add your specialist agents after creating the project.',`<form id="project-form" data-edit="${p?.id||''}">${field('Project name','name',p?.name||'',{required:true,max:80})}${field('What would you like to build?','brief',p?.brief||'',{textarea:true,help:'Describe the goal and what a good result looks like.'})}<p class="form-error" role="alert"></p><div class="modal-actions"><button type="button" class="secondary" data-action="close">Cancel</button><button class="primary" type="submit">${edit?'Save changes':'Create project'}</button></div></form>`);
}
function agentDialog(id) {
  if(!requireLocal())return;const p=currentProject(), a=p.agents.find(a=>a.id===id);
  modalShell(a?'Edit agent':'Add a specialist',a?'Change their display name or add project guidance. Their specialist toolkit stays intact.':'Choose the expertise your project needs. Each role uses its existing Swarmojo specialist toolkit.',`<form id="agent-form" data-id="${a?.id||''}" data-role="${a?.role||''}"><div class="field"><label for="agent-role">Specialist role</label><select id="agent-role" name="role" ${a?'disabled':''}>${state.roles.map(r=>`<option value="${r.id}" ${a?.role===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div><p class="role-description" id="role-description">${esc(state.roles.find(r=>r.id===(a?.role||'coder'))?.description)}</p>${field('Display name','name',a?.name||'Coder',{required:true,max:60})}${field('Additional project guidance (optional)','instructions',a?.instructions||'',{textarea:true,max:4000})}<label class="check-setting"><input type="checkbox" name="enabled" ${a?.enabled!==false?'checked':''}> Agent on</label><div class="field"><label for="agent-work-mode">Work mode</label><select id="agent-work-mode" name="work_mode"><option value="team" ${a?.work_mode!=='isolated'?'selected':''}>Team</option><option value="isolated" ${a?.work_mode==='isolated'?'selected':''}>Isolated</option></select></div>${field('Model override (optional)','model_id',a?.model_id||'',{max:160,help:'Uses the configured endpoint and key. Blank inherits the workspace model.'})}${field('Temperature override (optional)','temperature',a?.temperature??'',{type:'number',extra:'min="0" max="2" step="0.1"',help:'Blank inherits workspace settings. 0 is more consistent; higher values add variation.'})}<p class="form-error" role="alert"></p><div class="modal-actions">${a?`<button type="button" class="text-button danger" data-remove-agent="${a.id}">Remove from project</button>`:''}<button type="button" class="secondary" data-action="close">Cancel</button><button class="primary" type="submit">${a?'Save agent':'Add to project'}</button></div></form>`);
}
function settingsDialog() {
  if(!requireLocal())return; const s=state.settings;
  modalShell('Make this workspace yours','Connect an OpenAI-compatible model when you’re ready. Your API key stays in memory for this session only.',`<form id="settings-form"><div class="field-row">${field('Your name (optional)','display_name',s.display_name,{max:60})}${field('Main agent name','main_name',s.main_name,{required:true,max:60})}</div><hr class="divider">${field('Endpoint URL','base_url',s.base_url,{type:'url',help:'Example: http://127.0.0.1:11434/v1. Remote endpoints must use HTTPS.'})}${field('Model ID','model_id',s.model_id,{max:160,help:'Enter the exact model ID available at your endpoint.'})}${field('API key (if required)','api_key','',{type:'password',help:state.session_key_available?'A session key is available. Leave blank to keep it.':'Optional for local models. Never saved to disk.'})}<div class="field-row">${field('Maximum cost per call ($)','max_call_cost_usd',s.max_call_cost_usd,{type:'number',extra:'min="0" max="100" step="0.001"',help:'Use 0 for a free local model.'})}${field('Maximum output tokens','max_tokens',s.max_tokens,{type:'number',extra:'min="256" max="16384" step="1"'})}</div><div class="field-row">${field('Temperature','temperature',s.temperature??0.2,{type:'number',extra:'min="0" max="2" step="0.1"'})}${field('Request timeout (seconds)','timeout_seconds',s.timeout_seconds??90,{type:'number',extra:'min="5" max="300" step="1"'})}</div><p class="form-error" role="alert"></p><div class="modal-actions"><button type="button" class="secondary" data-action="close">Cancel</button><button class="primary" type="submit">Save settings</button></div></form>`);
}
async function submitMessage(form) {
  const input=$('textarea',form), text=input.value.trim(); if(!text)return;
  if(!requireLocal())return;
  if(!state.model_configured){toast('Connect a model to start chatting. Your draft is saved.');settingsDialog();return;}
  const target=view==='project'?activeScope():'main', team=view==='project'&&runByProject[scope]==='team';
  if(busyScopes.has(target))return;
  const request_id=crypto.randomUUID().replaceAll('-','');
  draftByScope[target]=''; saveSession(); busyScopes.add(target);
  if(view==='home')await navigate('main');
  render();
  try {
    const data=await api(`conversations/${target}/messages`,'POST',{text,team,request_id});
    if(activeScope()===target){conversation=data;render();$('#content').scrollTop=$('#content').scrollHeight;}else toast('Your agent has finished responding.');
  }catch(e){draftByScope[target]=text;toast(e.message);if(activeScope()===target)try{const data=await api(`conversations/${target}`);if(activeScope()===target)conversation=data;}catch{} }
  finally{busyScopes.delete(target);saveSession();if(activeScope()===target)render();}
}
document.addEventListener('input',e=>{if(e.target.id==='message-input'){draftByScope[view==='home'?'main':activeScope()]=e.target.value;saveSession();}});
document.addEventListener('change',e=>{
  if(e.target.id==='agent-role'){const role=state.roles.find(r=>r.id===e.target.value);$('#field-name').value=role.name;$('#role-description').textContent=role.description;}
});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();quickDialog();return;}if((e.ctrlKey||e.metaKey)&&e.key===','){e.preventDefault();settingsDialog();return;}if(e.target.id==='message-input'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('#composer').requestSubmit();}});
document.addEventListener('click',async e=>{
  const b=e.target.closest('button');if(!b)return;
  try {
    if(b.dataset.project)return await navigate('project',b.dataset.project);
    if(b.dataset.tab){projectTab=b.dataset.tab;render();saveSession();return;}
    if(b.dataset.draft){draftByScope[view==='home'?'main':activeScope()]=b.dataset.draft;saveSession();render();$('#message-input')?.focus();return;}
    if(b.dataset.editTask)return taskDialog(b.dataset.editTask);
    if(b.dataset.discussTask){const task=Object.values(conversation.tasks||{}).flat().find(t=>t.id===b.dataset.discussTask);draftByScope[scope]=`Help me work on this task: ${task.title}\n${task.description}`;projectTab='conversation';saveSession();render();$('#message-input').focus();return;}
    if(b.dataset.editAgent)return agentDialog(b.dataset.editAgent);
    if(b.dataset.removeAgent){state=await api(`projects/${scope}/agents/${b.dataset.removeAgent}`,'DELETE',{});conversation=await api(`conversations/${activeScope()}`);modal.close();render();toast('Agent removed from this project.');return;}
    if(b.dataset.approval){const target=activeScope();b.disabled=true;try{await api(`conversations/${target}/approvals/${b.dataset.approval}`,'POST',{fingerprint:b.dataset.fingerprint,decision:b.dataset.decision});toast(b.dataset.decision==='reject'?'Proposal rejected.':'Action completed. Receipt saved.');}finally{const data=await api(`conversations/${target}`);if(target===activeScope()){conversation=data;render();}}return;}
    const action=b.dataset.action;
    if(action==='quick-open')return quickDialog();
    if(action==='utilities')return utilitiesDialog();
    if(action==='knowledge-brief')return briefDialog();
    if(action==='portable')return portableDialog();
    if(action==='search-history')return searchDialog();
    if(['home','projects','main','settings'].includes(action))return await navigate(action);
    if(action==='menu')$('#sidebar').classList.toggle('open');
    if(action==='new-project')projectDialog();
    if(action==='edit-project')projectDialog(true);
    if(action==='add-agent')agentDialog();
    if(action==='configure')settingsDialog();
    if(action==='project-options')projectOptionsDialog();
    if(action==='new-task')taskDialog();
    if(action==='close')modal.close();
    if(action==='launch')launchDialog();
  }catch(error){const inline=modal.open?$('.form-error',modal):null;if(inline)inline.textContent=error.message;else toast(error.message);}
});
document.addEventListener('submit',async e=>{
  const form=e.target;e.preventDefault();if(form.id==='composer')return submitMessage(form);
  if(['web-form','search-form','knowledge-form','import-form','brief-form'].includes(form.id))return featureSubmit(form);
  const button=$('button[type="submit"]',form), body=Object.fromEntries(new FormData(form));button.disabled=true;
  try{
    if(form.id==='project-form'){
      const id=form.dataset.edit;state=await api(`projects${id?'/'+id:''}`,id?'PATCH':'POST',body);modal.close();await navigate('project',id||state.id);toast(id?'Project updated.':'Project created. Add agents whenever you’re ready.');
    }else if(form.id==='agent-form'){
      body.enabled=$('[name=enabled]',form).checked;body.temperature=body.temperature===''?null:Number(body.temperature);
      const id=form.dataset.id;body.role=body.role||form.dataset.role;state=await api(`projects/${scope}/agents${id?'/'+id:''}`,id?'PATCH':'POST',body);conversation=await api(`conversations/${activeScope()}`);modal.close();render();toast(id?'Agent updated. Specialist capabilities preserved.':'Specialist added to this project.');
    }else if(form.id==='project-options-form'){
      body.share_files=$('[name=share_files]',form).checked;body.budget_usd=Number(body.budget_usd);body.ignored_paths=body.ignored_paths.split('\n').map(x=>x.trim()).filter(Boolean);
      await api(`projects/${scope}/options`,'PUT',{...(await api(`conversations/${scope}`)).options,...body});conversation=await api(`conversations/${activeScope()}`);modal.close();render();toast('Project controls saved.');
    }else if(form.id==='memory-form'){
      conversation=await api(`projects/${scope}/options`,'PUT',{...projectOptions(),memory:body.memory});render();toast('Project memory saved.');
    }else if(form.id==='task-form'){
      body.blocked_by=new FormData(form).getAll('blocked_by');conversation=await api(`projects/${scope}/tasks${form.dataset.id?'/'+form.dataset.id:''}`,form.dataset.id?'PUT':'POST',body);modal.close();projectTab='tasks';render();toast(form.dataset.id?'Task updated.':'Task added.');
    }else if(form.id==='settings-form'){
      body.temperature=Number(body.temperature);body.timeout_seconds=Number(body.timeout_seconds);body.max_tokens=Number(body.max_tokens);body.max_call_cost_usd=Number(body.max_call_cost_usd);state=await api('settings','PUT',body);modal.close();render();toast('Settings saved.');
    }
  }catch(error){$('.form-error',form).textContent=error.message;button.disabled=false;}
});
function updateClock() {$('#clock').textContent=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});}
updateClock();setInterval(updateClock,60000);
try {state=await api('state');online=true;}catch{online=false;}
render();
// Recover a running conversation after a browser refresh, without redispatching a model request.
setInterval(async()=>{if(!online||!['main','project'].includes(view)||!conversation.busy||busyScopes.has(activeScope())||(view==='project'&&projectTab!=='conversation'))return;const target=activeScope();try{const data=await api(`conversations/${target}`);if(target===activeScope()){conversation=data;render();}}catch{}},3000);


function projectOptions(){return conversation.options||{memory:'',share_files:true,ignored_paths:[],action_mode:'commands',budget_usd:250};}
const taskLabels={backlog:'Backlog',in_progress:'In progress',blocked:'Blocked',review:'Review',done:'Done'};
const taskTransitions={backlog:['in_progress','blocked'],in_progress:['review','blocked'],blocked:['backlog','in_progress'],review:['done','in_progress'],done:[]};
function budgetPanel(){
  const b=conversation.budget;if(!b)return '';
  return `<section class="budget-panel"><div class="section-heading"><h3>Project budget</h3><button class="text-button" data-action="project-options">Edit</button></div><strong>$${Number(b.total_spend_usd).toFixed(2)} <span class="muted small">/ $${Number(b.organization_hard_cap_usd).toFixed(2)}</span></strong><progress max="${Math.max(0.01,b.organization_hard_cap_usd)}" value="${Math.min(b.organization_hard_cap_usd,b.total_spend_usd+b.reserved_cost_usd)}" aria-label="Project budget used"></progress><p class="small muted">Conservative call-cost accounting, not your provider’s invoice. Stops before a call would exceed the cap.</p>${selectedAgent()?'':`<button class="text-button spaced" data-tab="activity">Usage & activity ${icon('arrow')}</button>`}</section>`;
}
function tasksPanel(){
  const tasks=conversation.tasks||{};const p=currentProject();
  const owner=id=>id==='main'?state.settings.main_name:p.agents.find(a=>a.id===id)?.name||'Removed agent';
  return `<div class="section-heading"><div><h2>One step at a time.</h2><p class="small muted spaced">Plan, assign, and review. Moving a card records your assessment; it does not run an agent.</p></div><button class="primary" data-action="new-task">${icon('plus')} Add task</button></div><div class="task-board">${Object.entries(taskLabels).map(([status,label])=>`<section class="task-column"><h3>${label} <span class="muted">${(tasks[status]||[]).length}</span></h3>${(tasks[status]||[]).map(t=>`<article class="task-card glass"><span class="chip">${esc(t.priority)} priority</span><h3>${esc(t.title)}</h3><p>${esc(t.description)}</p><small>${esc(owner(t.assignee_id))}</small>${t.blocked_by.length?`<p class="small muted">Depends on: ${esc(t.blocked_by.map(id=>Object.values(tasks).flat().find(x=>x.id===id)?.title||id).join(', '))}</p>`:''}<div class="task-actions"><button class="text-button" data-edit-task="${t.id}">Edit</button><button class="text-button" data-discuss-task="${t.id}">Discuss task ${icon('arrow')}</button>${taskTransitions[status].length?`<select data-task-status="${t.id}" aria-label="Change status of ${esc(t.title)}"><option value="">Move to…</option>${taskTransitions[status].map(v=>`<option value="${v}">${taskLabels[v]}</option>`).join('')}</select>`:''}</div></article>`).join('')||'<p class="small muted">No tasks here.</p>'}</section>`).join('')}</div>`;
}
function memoryPanel(){return `<div class="section-heading"><button class="secondary" data-action="search-history">${icon('researcher')} Search notes & history</button><button class="secondary" data-action="portable">Project template</button></div><section class="feature-card glass"><div class="section-heading"><h2>Project memory</h2><span class="chip">YOU CURATE</span></div><p class="muted">Save decisions, conventions, and facts your team should remember. Shared only with this project’s agents when you send a message.</p><form id="memory-form">${field('Project notes','memory',projectOptions().memory,{textarea:true,max:12000,help:'These notes persist across restarts. They provide context, never permission to execute actions.'})}<p class="form-error" role="alert"></p><button class="primary" type="submit">Save memory</button></form></section>${knowledgePanel()}`;}
function activityPanel(){
  const b=conversation.budget;
  return `<section class="feature-card glass"><h2>Usage & limits</h2><p class="muted spaced">Measured tokens when the provider reports them; conservative reservations otherwise. Existing per-agent caps also apply.</p>${b?`<div class="usage-list">${b.per_agent.map(a=>`<div><strong>${esc(a.name)}</strong><span>${Number(a.tokens).toLocaleString()} / ${Number(a.token_cap).toLocaleString()} tokens</span><span>$${Number(a.spent).toFixed(2)} / $${Number(a.cap).toFixed(2)}</span></div>`).join('')}</div>`:''}</section><section class="feature-card glass spaced"><h2>Project activity</h2><p class="muted spaced">Runs, settings, tasks and approval decisions. Execution details stay in Approvals.</p><ol class="activity-list">${(conversation.activity||[]).map(e=>`<li><span class="activity-dot"></span><div><strong>${esc(e.kind.replaceAll('_',' '))}</strong><p>${esc(e.detail)}</p><time>${esc(new Date(e.created*1000).toLocaleString())}</time></div></li>`).join('')||'<p class="muted">Activity will appear as you work.</p>'}</ol></section>`;
}
function projectOptionsDialog(){const o=projectOptions();modalShell('Project controls','Choose the context and actions available to this project. Every file write and command still needs your approval.',`<form id="project-options-form"><div class="field"><label for="action-mode">Allowed actions</label><select id="action-mode" name="action_mode">${[['discuss','Discussion only'],['files','Propose files'],['commands','Propose files and sandbox commands']].map(([v,l])=>`<option value="${v}" ${o.action_mode===v?'selected':''}>${l}</option>`).join('')}</select></div><label class="check-setting"><input type="checkbox" name="share_files" ${o.share_files?'checked':''}> Include selected project files in model context</label>${field('Excluded paths (one glob per line)','ignored_paths',o.ignored_paths.join('\n'),{textarea:true,max:8000,help:'Examples: private/* or *.key. These files remain on disk but are omitted from automatic context.'})}${field('Project model budget ($)','budget_usd',o.budget_usd,{type:'number',extra:'min="0" max="100000" step="0.01"',help:'Lifetime budget for this project. 0 permits only calls declared free. Existing per-agent caps also apply.'})}<p class="form-error" role="alert"></p><div class="modal-actions"><button type="button" class="secondary" data-action="close">Cancel</button><button class="primary" type="submit">Save controls</button></div></form>`);}
function taskDialog(id){const p=currentProject(),allTasks=Object.values(conversation.tasks||{}).flat(),task=allTasks.find(t=>t.id===id),tasks=allTasks.filter(t=>t.id!==id);modalShell(task?'Edit task':'Add a project task','Define a concrete result and an owner. Dependencies must be completed before this task can move forward.',`<form id="task-form" data-id="${task?.id||''}">${field('Task title','title',task?.title||'',{required:true,max:160})}${field('Definition of done','description',task?.description||'',{textarea:true,max:6000})}<div class="field-row"><div class="field"><label for="task-owner">Owner</label><select id="task-owner" name="assignee_id"><option value="main">${esc(state.settings.main_name)}</option>${p.agents.map(a=>`<option value="${a.id}" ${task?.assignee_id===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div><div class="field"><label for="task-priority">Priority</label><select id="task-priority" name="priority">${['medium','high','low'].map(v=>`<option value="${v}" ${task?.priority===v?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="field"><label for="task-dependencies">Dependencies (optional)</label><select id="task-dependencies" name="blocked_by" multiple size="${Math.min(4,Math.max(2,tasks.length))}">${tasks.map(t=>`<option value="${t.id}" ${task?.blocked_by.includes(t.id)?'selected':''}>${esc(t.title)}</option>`).join('')}</select><small>Select existing tasks that must finish first.</small></div><p class="form-error" role="alert"></p><div class="modal-actions"><button type="button" class="secondary" data-action="close">Cancel</button><button class="primary" type="submit">${task?'Save task':'Create task'}</button></div></form>`);}
document.addEventListener('change',async e=>{if(!e.target.dataset.taskStatus)return;const id=e.target.dataset.taskStatus,status=e.target.value,target=scope;if(!status)return;e.target.disabled=true;try{const data=await api(`projects/${target}/tasks/${id}`,'PATCH',{status});if(activeScope()===target){conversation=data;render();}toast('Task status saved.');}catch(error){e.target.disabled=false;e.target.value='';toast(error.message);}});


function sessionKey(){return 'swarmojo.session.'+(state.workspace_id||'preview');}
function saveSession(){if(!online)return;try{localStorage.setItem(sessionKey(),JSON.stringify({view,scope,projectTab,drafts:draftByScope,team:teamByScope,run:runByProject}));}catch{}}
function recoveryPanel(){return (conversation.recovery||[]).length?`<details class="recovery glass"><summary>Recover a previous request</summary><p class="small muted">Saved replies and approvals remain available. Restoring a draft never sends it or repeats an action.</p>${conversation.recovery.map((r,i)=>`<div class="recovery-row"><span>${esc(r.status)} · ${esc(r.input.text.slice(0,100))}</span><button class="text-button" data-recover="${i}">Restore draft</button></div>`).join('')}</details>`:'';}
function quickDialog(){modalShell('Go somewhere','Jump to a project or workspace section. Ctrl+K / ⌘K opens this menu.',`<label for="quick-query" class="small muted">Find a project or section</label><input id="quick-query" class="quick-query" type="search" autocomplete="off" placeholder="Start typing…"><div id="quick-results" class="quick-results"></div>`);renderQuick();$('#quick-query').focus();}
function quickEntries(){return [{label:'Overview',view:'home'},{label:state.settings.main_name,view:'main'},{label:'All projects',view:'projects'},{label:'Settings',view:'settings'},...state.projects.map(p=>({label:p.name,view:'project',id:p.id})),...(view==='project'?(selectedAgent()?['conversation','files','approvals']:['conversation','tasks','memory','web','files','approvals','activity']).map(tab=>({label:currentProject().name+' / '+tab,view:'project',id:scope,tab})):[])];}
function renderQuick(){const query=$('#quick-query').value.toLowerCase();$('#quick-results').innerHTML=quickEntries().map((entry,i)=>({...entry,i})).filter(e=>e.label.toLowerCase().includes(query)).slice(0,30).map(e=>`<button class="nav-button" data-quick="${e.i}">${icon(e.view==='project'?'folder':'arrow')} ${esc(e.label)}</button>`).join('')||'<p class="muted">No matching places.</p>';}
function portableDialog(){if(!requireLocal())return;modalShell('Portable project templates','Move a project’s brief, specialist setup and controls between Swarmojo workspaces. Templates contain no connection keys, history, sources, files or saved memory. Review your brief and agent guidance before sharing.',`${view==='project'?`<button class="primary" data-action="export-template">Download ${esc(currentProject().name)} template</button><hr class="divider">`:''}<form id="import-form"><div class="field"><label for="template-file">Import a Swarmojo JSON template</label><input id="template-file" name="template" type="file" accept=".json,application/json" required><small>Creates a new project. Does not run agents or change your model connection.</small></div><p class="form-error" role="alert"></p><button class="primary" type="submit">Import project</button></form>`);}
function searchDialog(){if(!requireLocal())return;modalShell('Search this conversation',selectedAgent()?'Search only this specialist’s isolated conversation.':view==='project'?'Search this project’s notes, saved references and conversation.':'Search your Main agent conversation.',`<form id="search-form">${field('Search for','query','',{id:'search-query',required:true,max:160,extra:'minlength="2"'})}<p class="form-error" role="alert"></p><button type="submit" class="primary">Search</button></form><div id="search-results" class="spaced"></div>`);}
function knowledgePanel(){return `<section class="feature-card glass spaced"><h2>ROMS knowledge</h2><button class="secondary spaced" data-action="knowledge-brief">Export selected task brief</button><p class="muted spaced">Search your existing local index. Only excerpts you select become project context. Results are indexed snapshots; original files are not revalidated.</p><form id="knowledge-form">${field('Search ROMS','query','',{required:true,max:160,extra:'minlength="2"'})}<p class="form-error" role="alert"></p><button class="secondary" type="submit">Search knowledge</button></form><div id="knowledge-results" class="spaced"></div></section>${sourceCards('roms')}`;}
function sourceCards(kind){return (conversation.sources||[]).filter(s=>s.kind===kind).map(s=>`<article class="feature-card source-card glass spaced"><div class="section-heading"><h3>${esc(s.title)}</h3><span class="chip">${kind==='roms'?'ROMS SNAPSHOT':'WEB SNAPSHOT'}</span></div><p class="workspace-path">${esc(s.metadata.url||s.metadata.source_id)} · ${esc(new Date(s.created*1000).toLocaleString())}</p><details><summary>Read saved text${s.metadata.truncated?' (truncated)':''}</summary><pre>${esc(s.content)}</pre>${s.metadata.links?.length?`<p class="small muted">Page links (open separately)</p><ul>${s.metadata.links.map(url=>`<li><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(url)}</a></li>`).join('')}</ul>`:''}</details><label class="check-setting"><input type="checkbox" data-source="${s.id}" ${s.enabled?'checked':''}> Use in project context</label><p class="small muted">At most four selected references, 3,000 characters each. Reference text cannot authorize actions.</p><button class="text-button danger spaced" data-remove-source="${s.id}">Remove saved reference</button></article>`).join('');}
function webPanel(){return `<section class="feature-card glass"><h2>A little research, in reach.</h2><p class="muted spaced">Read a public page as text and save a snapshot in this project. No login, scripts or cookies. Pages are fetched only when you ask; select a saved reference to share it with your agents.</p><form id="web-form">${field('Public page URL','url','',{required:true,type:'url',max:2000,help:'HTTP or HTTPS on ports 80/443. HTML and plain text, up to 1 MB per page.'})}<p class="form-error" role="alert"></p><button class="primary" type="submit">Read page</button></form></section>${sourceCards('web')}`;}
let knowledgeResults=[],knowledgeQuery='';
async function featureSubmit(form){const target=form.id==='search-form'?activeScope():scope,version=navigationVersion,button=$('button[type="submit"]',form),body=Object.fromEntries(new FormData(form));button.disabled=true;$('.form-error',form).textContent='';try{
  if(form.id==='brief-form'){const epoch=form.dataset.epoch||'0';const data=await api(`projects/${target}/knowledge-brief`,'POST',{...body,source_ids:JSON.parse(form.dataset.sources)});if(!form.isConnected||version!==navigationVersion||epoch!==(form.dataset.epoch||'0'))return;const preview=$('#brief-preview');preview.value=data.markdown;$('#brief-output').hidden=false;$('#brief-download').onclick=()=>{const url=URL.createObjectURL(new Blob([preview.value],{type:'text/markdown'}));const a=document.createElement('a');a.href=url;a.download='Swarmojo-task-brief.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};}
  if(form.id==='import-form'){const file=$('[type=file]',form).files[0];if(!file||file.size>128000)throw new Error('Choose a JSON template smaller than 128 KB.');state=await api('configurations/import','POST',JSON.parse(await file.text()));modal.close();await navigate('project',state.id);toast('Project imported. Your model connection is unchanged.');}
  if(form.id==='web-form'){const data=await api(`projects/${target}/web`,'POST',body);if(target===scope&&version===navigationVersion){conversation=data;render();}toast('Page saved. Select it to include it in project context.');}
  if(form.id==='search-form'){const data=await api(`conversations/${target}/search`,'POST',body);if($('#search-results')&&version===navigationVersion)$('#search-results').innerHTML=data.results.map(r=>`<article class="search-result"><span class="chip">${esc(r.kind)}</span><strong>${esc(r.title)}</strong><p>${esc(r.excerpt)}</p></article>`).join('')||'<p class="muted">No matches in this conversation.</p>';}
  if(form.id==='knowledge-form'){const data=await api(`projects/${target}/knowledge`,'POST',body);if(!$('#knowledge-results')||version!==navigationVersion)return;knowledgeResults=data.sources;knowledgeQuery=body.query;$('#knowledge-results').innerHTML=data.sources.map((r,i)=>`<article class="search-result"><strong>${esc(r.title)}</strong><p class="workspace-path">${esc(r.source_id)}</p><pre>${esc(r.excerpt)}</pre><button class="secondary" data-select-knowledge="${i}">Add to project context</button></article>`).join('')||`<p class="muted">${data.status==='unavailable'?'No local ROMS index yet. Index your knowledge with Swarmojo, then search here.':'No indexed matches.'}</p>`;}
}catch(error){if(form.isConnected)$('.form-error',form).textContent=error.message;else toast(error.message);}finally{button.disabled=false;}}
document.addEventListener('input',e=>{if(e.target.id==='quick-query')renderQuick();});
document.addEventListener('keydown',e=>{if(e.target.id==='quick-query'&&e.key==='Enter'){e.preventDefault();$('#quick-results button')?.click();}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const target=scope;try{
  if(b.dataset.quick!==undefined){const entry=quickEntries()[Number(b.dataset.quick)];modal.close();await navigate(entry.view,entry.id);if(entry.tab){projectTab=entry.tab;render();saveSession();}}
  if(b.dataset.recover!==undefined){const r=conversation.recovery[Number(b.dataset.recover)];draftByScope[activeScope()]=r.input.text;if(!selectedAgent())runByProject[scope]=r.input.team?'team':'main';saveSession();render();$('#message-input')?.focus();toast('Draft restored. Review saved replies before sending.');}
  if(b.dataset.action==='export-template'){const data=await api(`projects/${target}/configuration`);const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)+'\n'],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='swarmojo-project.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Template downloaded. Review project guidance before sharing.');}
  if(b.dataset.removeSource){b.disabled=true;const data=await api(`projects/${target}/sources/${b.dataset.removeSource}`,'DELETE',{});if(target===activeScope()){conversation=data;render();}}
  if(b.dataset.selectKnowledge!==undefined){b.disabled=true;const r=knowledgeResults[Number(b.dataset.selectKnowledge)];const data=await api(`projects/${target}/knowledge-selection`,'POST',{query:knowledgeQuery,source_id:r.source_id,indexed_chunk_sha256:r.indexed_chunk_sha256});if(target===activeScope()){conversation=data;render();}toast('Indexed excerpt added to project context.');}
}catch(error){b.disabled=false;toast(error.message);}});
document.addEventListener('change',async e=>{if(!e.target.dataset.source)return;const target=scope,input=e.target;input.disabled=true;try{const data=await api(`projects/${target}/sources/${input.dataset.source}`,'PATCH',{enabled:input.checked});if(target===activeScope()){conversation=data;render();}}catch(error){input.checked=!input.checked;input.disabled=false;toast(error.message);}});
if(online){try{const saved=JSON.parse(localStorage.getItem(sessionKey())||'{}');draftByScope=Object.fromEntries(Object.entries(saved.drafts||{}).filter(([k,v])=>typeof v==='string'&&(k==='main'||state.projects.some(p=>p.id===k||p.agents.some(a=>k===`${p.id}.${a.id}`)))).map(([k,v])=>[k,v.slice(0,12000)]));teamByScope=saved.team||{};runByProject=saved.run||Object.fromEntries(Object.entries(teamByScope).map(([k,v])=>[k,v?'team':'main']));const tab=saved.projectTab;if(['home','main','projects','settings','project'].includes(saved.view)&&(saved.view!=='project'||state.projects.some(p=>p.id===saved.scope))){await navigate(saved.view,saved.scope);if(view==='project'&&['conversation','tasks','memory','web','files','approvals','activity'].includes(tab)){projectTab=tab;saveSession();}}render();}catch{render();}}


document.addEventListener('change',async e=>{
  const input=e.target;
  if(input.id==='project-run-mode'){runByProject[scope]=input.value;projectTab='conversation';saveSession();await loadConversation();return;}
  const id=input.dataset.agentEnabled||input.dataset.agentMode;if(!id)return;
  const projectId=scope;input.disabled=true;
  const changes=input.dataset.agentEnabled?{enabled:input.checked}:{work_mode:input.value};
  try{state=await api(`projects/${projectId}/agents/${id}/participation`,'PATCH',changes);if(scope===projectId){await loadConversation();}toast('Agent settings saved. Existing responses can finish.');}
  catch(error){input.disabled=false;render();toast(error.message);}
});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-open-isolated]');if(!b)return;runByProject[scope]=b.dataset.openIsolated;projectTab='conversation';saveSession();await loadConversation();});

function utilitiesDialog(){if(!requireLocal())return;modalShell('Local utilities','Two Buzburg tools for work that benefits from exact checks. Download and open the HTML file in your browser. File contents stay in that tool; they are not uploaded to Swarmojo or your model.',`<section class="feature-card"><h3>Compare CSV exports</h3><p>Row Witness finds added, removed and changed records, with column mapping and explicit duplicate-key conflicts. Export the report for your team.</p><a class="primary" href="/utilities/row-witness.html" download>Download CSV comparer</a></section><section class="feature-card spaced"><h3>Check a folder or ZIP before handoff</h3><p>Path Carry checks filenames, case and Unicode collisions, reserved names and archive paths. It reads metadata without extracting or renaming files.</p><a class="primary" href="/utilities/path-carry.html" download>Download filename checker</a></section>`);}
function briefDialog(){if(!requireLocal())return;const selected=(conversation.sources||[]).filter(s=>s.kind==='roms'&&s.enabled);if(!selected.length){toast('Select a ROMS reference for project context first.');return;}modalShell('Take your project evidence with you','Build a portable brief from the ROMS references selected in this project. Preview before sharing; copied excerpts are snapshots and the receiving client’s data settings apply.',`<form id="brief-form" data-sources="${esc(JSON.stringify(selected.map(s=>s.id)))}">${field('Task','task','',{textarea:true,required:true,max:2000})}${field('Constraints','constraints','',{textarea:true,max:4000})}<p class="form-error" role="alert"></p><button type="submit" class="primary">Preview brief</button></form><div id="brief-output" hidden class="spaced"><label for="brief-preview">Review the full brief</label><textarea id="brief-preview" rows="14" readonly></textarea><button id="brief-download" class="secondary spaced">Download Markdown</button></div>`);$('#brief-form').addEventListener('input',()=>{$('#brief-form').dataset.epoch=String(Number($('#brief-form').dataset.epoch||0)+1);$('#brief-output').hidden=true;$('#brief-preview').value='';});}
